begin;
do $$
declare results text[]:='{}';
begin
  if private.weekly_hours_valid(array['mon-day','thu-eve']) and private.weekly_hours_valid(array['mon-day','mon-day']) then results:=array_append(results,'PASS legacy selections retained');else results:=array_append(results,'FAIL legacy selections');end if;
  if private.weekly_hours_valid(array['mon@1140-1260','wed@720-780','wed@1080-1200']) then results:=array_append(results,'PASS exact and split hours accepted');else results:=array_append(results,'FAIL exact hours');end if;
  if private.weekly_hours_valid('{}') and private.weekly_hours_valid(null) then results:=array_append(results,'PASS explicit empty and skipped retained');else results:=array_append(results,'FAIL empty');end if;
  if not private.weekly_hours_valid(array['mon@1260-1140']) and not private.weekly_hours_valid(array['mon@0-1441']) and not private.weekly_hours_valid(array['mon@0-0']) and not private.weekly_hours_valid(array[null]) then results:=array_append(results,'PASS invalid ranges refused');else results:=array_append(results,'FAIL invalid range');end if;
  if not private.weekly_hours_valid(array['mon@1140-1260','mon@1200-1320']) and not private.weekly_hours_valid(array['mon@1140-1260','mon@1140-1260']) then results:=array_append(results,'PASS overlapping and duplicate exact ranges refused');else results:=array_append(results,'FAIL overlap');end if;
  if private.weekly_hours_valid(array['mon@1140-1200','mon@1200-1260','sun@1320-1440']) then results:=array_append(results,'PASS adjacent and midnight ranges accepted');else results:=array_append(results,'FAIL adjacent ranges');end if;
  if private.matches_weekly_hours(array['mon@1140-1260'],'2026-11-09 19:00 America/New_York','America/New_York') and not private.matches_weekly_hours(array['mon@1140-1260'],'2026-11-09 21:00 America/New_York','America/New_York') and not private.matches_weekly_hours(array['mon@1140-1260'],'2026-11-10 19:00 America/New_York','America/New_York') then results:=array_append(results,'PASS ranking respects exact start end and weekday');else results:=array_append(results,'FAIL ranking boundary');end if;
  if private.matches_weekly_hours(array['sun@1140-1260'],'2026-10-25 19:30 America/New_York','America/New_York') and private.matches_weekly_hours(array['sun@1140-1260'],'2026-11-01 19:30 America/New_York','America/New_York') then results:=array_append(results,'PASS ranking uses local time across DST');else results:=array_append(results,'FAIL DST');end if;
  if not private.matches_weekly_hours(array['sun@150-210'],'2026-03-08 03:00 America/New_York','America/New_York') and private.matches_weekly_hours(array['sun@60-90'],'2026-11-01 05:15Z','America/New_York') and not private.matches_weekly_hours(array['sun@60-90'],'2026-11-01 06:15Z','America/New_York') then results:=array_append(results,'PASS nonexistent and repeated clock hours agree with Calendar');else results:=array_append(results,'FAIL clock edge');end if;
  if private.matches_weekly_hours(array['mon@1140-1260'],'2026-11-09 19:00 America/New_York','Europe/London') then results:=array_append(results,'PASS exact hours retain displayed timezone');else results:=array_append(results,'FAIL timezone');end if;
  if strpos(pg_get_functiondef('public.home_suggestions(integer)'::regprocedure),'private.matches_weekly_hours(v_windows,sg.starts_at,v_tz)')>0 and strpos(pg_get_functiondef('public.home_suggestions(integer)'::regprocedure),'private.matches_weekly_hours(v_windows,fs.starts_at,v_tz)')>0 then results:=array_append(results,'PASS ranking score and explanation updated together');else results:=array_append(results,'FAIL ranking integration');end if;
  if exists(select 1 from pg_constraint c where c.conrelid='public.profile_private'::regclass and c.conname='profile_private_free_windows_valid' and pg_get_constraintdef(c.oid) like '%weekly_hours_valid%') then results:=array_append(results,'PASS setting validates exact hours');else results:=array_append(results,'FAIL constraint');end if;
  if not has_function_privilege('anon','private.weekly_hours_valid(text[])','execute') and not has_function_privilege('anon','private.matches_weekly_hours(text[],timestamptz,text)','execute') then results:=array_append(results,'PASS no anonymous helper grant');else results:=array_append(results,'FAIL grants');end if;
  raise exception 'RESULTS: %', array_to_string(results, ', ');
end $$;
rollback;
